1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Kept as a separate additive term rather than folded into a `policyBase * 1.1`
51	// factor: that is not float-equivalent (100 * 1.1 === 110.00000000000001), and
52	// the final rounding-up turns the stray ulp into a whole extra gold piece.
53	// Do not "simplify".
54	const firstInsuranceSurcharge = (policyBase: number): number =>
55	  policyBase * FIRST_INSURANCE_RATE;
56	
57	// The MHPCO rounds premiums in its own favour.
58	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
59	
60	const COMPONENT_BLOCK_SIZE = 3;
61	const COMPONENT_BLOCK_PREMIUM = 60;
62	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
63	
64	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
65	
66	// A group is every item of one single type, so a group is always non-empty
67	// and homogeneous — the block rule below relies on both.
68	interface TypeGroup {
69	  type: string;
70	  items: Item[];
71	}
72	
73	const groupByType = (items: Item[]): TypeGroup[] =>
74	  [
75	    ...items.reduce(
76	      (groups, item) =>
77	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
78	      new Map<string, Item[]>(),
79	    ),
80	  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));
81	
82	const formsComponentBlock = (group: TypeGroup): boolean =>
83	  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);
84	
85	const sumOfItemBasePremiums = (items: Item[]): number =>
86	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
87	
88	const groupBasePremium = (group: TypeGroup): number =>
89	  formsComponentBlock(group)
90	    ? COMPONENT_BLOCK_PREMIUM
91	    : sumOfItemBasePremiums(group.items);
92	
93	const policyBasePremium = (items: Item[]): number =>
94	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
95	
96	const CURSE_SURCHARGE_RATE = 0.5;
97	
98	// Item-specific modifiers are charged on the affected item's own base premium,
99	// unlike the policy-wide modifiers which apply to the sum of all of them.
100	const curseSurcharge = (item: Item): number =>
101	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
102	
103	const HIGH_ENCHANTMENT_LEVEL = 5;
104	const HIGH_ENCHANTMENT_RATE = 0.3;
105	
106	// An unenchanted item may leave `enchantment` unset; absent means level 0.
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
109	
110	const highEnchantmentSurcharge = (item: Item): number =>
111	  isHighlyEnchanted(item) ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE : 0;
112	
113	const itemSurcharge = (item: Item): number =>
114	  curseSurcharge(item) + highEnchantmentSurcharge(item);
115	
116	const totalItemSurcharges = (items: Item[]): number =>
117	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
118	
119	const LOYALTY_YEARS = 2;
120	const LOYALTY_DISCOUNT_RATE = 0.2;
121	
122	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
123	  customer.yearsWithMHPCO >= LOYALTY_YEARS
124	    ? policyBase * LOYALTY_DISCOUNT_RATE
125	    : 0;
126	
127	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
128	
129	// Every contract after the customer's first is a follow-up. Which contract
130	// this is depends on how many quotes preceded it in the scenario, not on the
131	// customer record.
132	const followUpDiscount = (precedingQuotes: number, policyBase: number): number =>
133	  precedingQuotes > 0 ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
134	
135	// Policy-wide modifiers are charged on the sum of all item base premiums,
136	// unlike the item-specific ones above. Each returns a signed adjustment:
137	// surcharges positive, discounts negative.
138	const policyModifiers = (
139	  policyBase: number,
140	  customer: Customer,
141	  precedingQuotes: number,
142	): number =>
143	  firstInsuranceSurcharge(policyBase) -
144	  loyaltyDiscount(customer, policyBase) -
145	  followUpDiscount(precedingQuotes, policyBase);
146	
147	const quotePremium = (
148	  items: Item[],
149	  customer: Customer,
150	  precedingQuotes: number,
151	): number => {
152	  const policyBase = policyBasePremium(items);
153	  return roundedInMHPCOsFavour(
154	    policyBase +
155	      policyModifiers(policyBase, customer, precedingQuotes) +
156	      totalItemSurcharges(items) +
157	      PROCESSING_FEE,
158	  );
159	};
160	
161	const runStep = (
162	  step: Step,
163	  customer: Customer,
164	  precedingQuotes: number,
165	): StepResult => {
166	  if (step.op === "quote") {
167	    return { premium: quotePremium(step.items, customer, precedingQuotes) };
168	  }
169	  throw new Error(`unsupported step: ${step.op}`);
170	};
171	
172	export const runScenario = (scenario: Scenario): ScenarioResult => {
173	  let precedingQuotes = 0;
174	  const results = scenario.steps.map((step) => {
175	    const result = runStep(step, scenario.customer, precedingQuotes);
176	    if (step.op === "quote") precedingQuotes += 1;
177	    return result;
178	  });
179	  return { results };
180	};
