// Policy-wide modifiers are charged on the sum of all item base premiums,
// unlike the item-specific ones above. Each returns a signed adjustment:
// surcharges positive, discounts negative.
const policyModifiers = (policyBase: number, context: QuoteContext): number =>
  firstInsuranceSurcharge(policyBase) -
  loyaltyDiscount(context.customer, policyBase) -
  followUpDiscount(context.precedingQuotes, policyBase);

const quotePremium = (items: Item[], context: QuoteContext): number => {
  const policyBase = policyBasePremium(items);
  return roundedInMHPCOsFavour(
    policyBase +
      policyModifiers(policyBase, context) +
      totalItemSurcharges(items) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, context: QuoteContext): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, context) };
  }
  throw new Error(`unsupported step: ${step.op}`);
};

const countQuotes = (steps: Step[]): number =>
  steps.filter((step) => step.op === "quote").length;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    runStep(step, {
      customer: scenario.customer,
      precedingQuotes: countQuotes(scenario.steps.slice(0, index)),
    }),
  ),
});

// Everything a quote needs beyond its own items: who is buying, and where in
// the scenario the quote sits. Bundled so callers thread one named value
// rather than a trail of bare parameters.
interface QuoteContext {
  customer: Customer;
  precedingQuotes: number;
}

